package com.example.data.repository

data class Hadith(
    val id: Int,
    val text: String,
    val narrator: String,
    val chapter: String,
    val explanation: String
)

object HadithRepository {

    val chapters = listOf(
        "الكل",
        "فضل الصلاة والمسجد والطهور",
        "فضل الصيام ورمضان والقيام",
        "فضل الزكاة والصدقة والإنفاق",
        "فضل بر الوالدين وصلة الرحم",
        "فضل الذكر والدعاء والاستغفار",
        "فضل طلب العلم وتلاوة القرآن",
        "حسن الخُلُق والأخلاق الإسلامية",
        "فضل عمل الخير وإفشاء السلام",
        "التوبة والصبر والتوكل على الله",
        "أذكار اليوم والليلة وسُنَن المصطفى"
    )

    val hadithsList: List<Hadith> = generateAuthenticHadiths()

    private fun generateAuthenticHadiths(): List<Hadith> {
        val list = mutableListOf<Hadith>()
        var currentId = 1

        // 1. فضل الصلاة والمسجد والطهور
        val prayerHadiths = listOf(
            Triple("بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالحَجِّ، وَصَوْمِ رَمَضَانَ.", "متفق عليه (البخاري ومسلم)", "أساس الدين الخمسة والعماد المعتمد للقبول."),
            Triple("مَنْ تَطَهَّرَ فِي بَيْتِهِ، ثُمَّ مَشَى إِلَى بَيْتٍ مِنْ بُيُوتِ اللهِ لِيَقْضِيَ فَرِيضَةً مِنْ فَرَائِضِ اللهِ، كَانَتْ خَطْوَتَاهُ إِحْدَاهُمَا تَحُطُّ خَطِيئَةً، وَالأُخْرَى تَرْفَعُ دَرَجَةً.", "رواه مسلم", "فضل المشي إلى الصلاة والتردد على المساجد."),
            Triple("أَرَأَيْتُمْ لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ، هَلْ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ؟ قَالُوا: لاَ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ، قَالَ: فَذَلِكَ مَثَلُ الصَّلَوَاتِ الخَمْسِ، يَمْحُو اللَّهُ بِهِنَّ الخَطَايَا.", "متفق عليه", "الصلاة تمحو الذنوب والخطايا اليومية."),
            Triple("صَلاَةُ الجَمَاعَةِ تَفْضُلُ صَلاَةَ الفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً.", "متفق عليه", "عظم أجر صلاة الجماعة في المسجد."),
            Triple("الطُّهُورُ شَطْرُ الإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلأُ الْمِيزَانَ، وَسُبْحَانَ اللهِ وَالْحَمْدُ لِلَّهِ تَمْلآنِ مَا بَيْنَ السَّمَاوَاتِ وَالأَرْضِ، وَالصَّلاَةُ نُورٌ.", "رواه مسلم", "أهمية الطهارة والذكر والصلاة نوار للصاحب."),
            Triple("مَنْ صَلَّى الْبَرَدَيْنِ دَخَلَ الْجَنَّةَ.", "متفق عليه", "البردين هما صلاتا الفجر والعصر، والمحافظة عليهما سبب لدخول الجنة."),
            Triple("مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ مِثْلَهُ فِي الجَنَّةِ.", "متفق عليه", "فضل عمارة المساجد وبنائها لوجه الله."),
            Triple("بَشِّرِ الْمَشَّائِينَ فِي الظُّلَمِ إِلَى الْمَسَاجِدِ بِالنُّورِ التَّامِّ يَوْمَ الْقِيَامَةِ.", "رواه أبو داود والترمذي وصححه الألباني", "بشارة من يمشي للصلاة في الظلمات بالفجر والعشاء."),
            Triple("الصَّلَوَاتُ الْخَمْسُ، وَالْجُمُعَةُ إِلَى الْجُمُعَةِ، وَرَمَضَانُ إِلَى رَمَضَانَ، مُكَفِّرَاتٌ مَا بَيْنَهُنَّ إِذَا اجْتَنَبَ الْكَبَائِرَ.", "رواه مسلم", "تكفير السيئات بالعبادات الخمس."),
            Triple("إِنَّ فِي اللَّيْلِ لَسَاعَةً لاَ يُوَافِقُهَا رَجُلٌ مُسْلِمٌ يَسْأَلُ اللهَ خَيْرًا مِنْ أَمْرِ الدُّنْيَا وَالآخِرَةِ إِلاَّ أَعْطَاهُ إِيَّاهُ، وَذَلِكَ كُلَّ لَيْلَةٍ.", "رواه مسلم", "فضل قيام الليل والاستغفار بالسحر.")
        )

        prayerHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "فضل الصلاة والمسجد والطهور", exp))
        }

        // 2. فضل الصيام ورمضان والقيام
        val fastingHadiths = listOf(
            Triple("مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.", "متفق عليه", "فضل صيام شهر رمضان الإيماني خالصاً لله."),
            Triple("مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.", "متفق عليه", "عظم ليلة القدر ومكانتها في المغفرة."),
            Triple("الصِّيَامُ جُنَّةٌ، فَإِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلاَ يَرْفُثْ وَلاَ يَصْخَبْ، فَإِنْ سَابَّهُ أَحَدٌ أَوْ قَاتَلَهُ فَلْيَقُلْ: إِنِّي امْرُؤٌ صَائِمٌ.", "متفق عليه", "الصيام وقاية وأخلاق وتهذيب للنفس."),
            Triple("قَالَ اللَّهُ كُلُّ عَمَلِ ابْنِ آدَمَ لَهُ إِلاَّ الصِّيَامَ، فَإِنَّهُ لِي وَأَنَا أَجْزِي بِهِ.", "متفق عليه", "الحديث القدسي العظيم في ثواب الصائمين."),
            Triple("لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا: إِذَا أَفْطَرَ فَرِحَ، وَإِذَا لَقِيَ رَبَّهُ فَرِحَ بِصَوْمِهِ.", "متفق عليه", "جزاء وفرحة الصائم بالدنيا والآخرة."),
            Triple("إِنَّ فِي الجَنَّةِ بَابًا يُقَالُ لَهُ الرَّيَّانُ، يَدْخُلُ مِنْهُ الصَّائِمُونَ يَوْمَ القِيَامَةِ لاَ يَدْخُلُ مِنْهُ أَحَدٌ غَيْرُهُمْ.", "متفق عليه", "باب الريان المختص بعباد الله الصائمين."),
            Triple("تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً.", "متفق عليه", "البركة في السحور واتباع سنة النبي صلى الله عليه وسلم."),
            Triple("مَنْ أَفْطَرَ صَائِمًا كَانَ لَهُ مِثْلُ أَجْرِهِ غَيْرَ أَنَّهُ لاَ يَنْقُصُ مِنْ أَجْرِ الصَّائِمِ شَيْئًا.", "رواه الترمذي وقال حديث حسن صحيح", "فضل تفطير الصائمين ونيل مثل أجورهم."),
            Triple("مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ.", "رواه مسلم", "أجر صيام ست من شوال كصيام السنة كاملة."),
            Triple("أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللهِ الْمُحَرَّمُ، وَأَفْضَلُ الصَّلاَةِ بَعْدَ الْفَرِيضَةِ صَلاَةُ اللَّيْلِ.", "رواه مسلم", "فضل صيام شهر الله المحرم وصلاة القيام.")
        )

        fastingHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "فضل الصيام ورمضان والقيام", exp))
        }

        // 3. فضل الزكاة والصدقة والإنفاق
        val charityHadiths = listOf(
            Triple("مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ.", "رواه مسلم", "الصدقة تبارك المال ولا تنقصه وتزيده خيراً."),
            Triple("اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ.", "متفق عليه", "أهمية البذل والإنفاق ولو بالقليل الدائم."),
            Triple("إِنَّ الصَّدَقَةَ لَتُطْفِئُ عَنْ أَهْلِهَا حَرَّ الْقُبُورِ، وَإِنَّمَا يَسْتَظِلُّ الْمُؤْمِنُ يَوْمَ الْقِيَامَةِ فِي ظِلِّ صَدَقَتِهِ.", "رواه الطبراني وصححه الألباني", "ظل الصدقة ووقايتها من حر القيامة."),
            Triple("كُلُّ امْرِئٍ فِي ظِلِّ صَدَقَتِهِ حَتَّى يُفْضَى بَيْنَ النَّاسِ.", "رواه أحمد وصححه ابن حبان", "الاستظلال بالصدقات يوم المحشر."),
            Triple("الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ.", "متفق عليه", "فضل الإنفاق والتعفف والعمل للرزق."),
            Triple("مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلاَّ مَلَكَانِ يَنْزِلاَنِ فَيَقُولُ أَحَدُهُمَا: اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الآخَرُ: اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا.", "متفق عليه", "دعاء الملائكة اليومي للمنفقين بالخلف والبركة."),
            Triple("السَّاعِي عَلَى الأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللهِ، وَأَحْسِبُهُ قَالَ: وَكَالْقَائِمِ لاَ يَفْتُرُ وَبِالصَّائِمِ لاَ يُفْطِرُ.", "متفق عليه", "عظم ثواب رعاية المساكين والأرامل."),
            Triple("صَنَائِعُ الْمَعْرُوفِ تَقِي مَصَارِعَ السُّوءِ، وَصَدَقَةُ السِّرِّ تُطْفِئُ غَضَبَ الرَّبِّ.", "رواه الطبراني وصححه الألباني", "أثر فعل الخير والصدقة في دفع البلاء."),
            Triple("تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ.", "رواه الترمذي وصححه الألباني", "الصدقات المعنوية والكلمة الطيبة والابتسامة."),
            Triple("إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلاَّ مِنْ ثَلاَثَةٍ: إِلاَّ مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ.", "رواه مسلم", "الصدقة الجارية والأثر الباقي للإنسان.")
        )

        charityHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "فضل الزكاة والصدقة والإنفاق", exp))
        }

        // 4. فضل بر الوالدين وصلة الرحم
        val parentsHadiths = listOf(
            Triple("رَغِمَ أَنْفُ، ثُمَّ رَغِمَ أَنْفُ، ثُمَّ رَغِمَ أَنْفُ، قِيلَ: مَنْ يَا رَسُولَ اللهِ؟ قَالَ: مَنْ أَدْرَكَ أَبَوَيْهِ عِنْدَ الْكِبَرِ، أَحَدَهُمَا أَوْ كِلَيْهِمَا فَلَمْ يَدْخُلِ الْجَنَّةَ.", "رواه مسلم", "التحذير من التقصير في حق الوالدين عند الكبر."),
            Triple("جَاءَ رَجُلٌ إِلَى رَسُولِ اللهِ فَقَالَ: مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: أُمُّكَ، قَالَ: ثُمَّ مَنْ؟ قَالَ: ثُمَّ أَبُوكَ.", "متفق عليه", "عظم حق الأم وتقديمها بالبر ثلاثة أضعاف."),
            Triple("مَنْ سَرَّهُ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَأَنْ يُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ.", "متفق عليه", "صلة الرحم سبب للبركة في العمر والرزق."),
            Triple("لاَ يَدْخُلُ الجَنَّةَ قَاطِعُ رَحِمٍ.", "متفق عليه", "التحذير الشديد من قطيعة الأرحام والقرابات."),
            Triple("الرَّحِمُ مُعَلَّقَةٌ بِالْعَرْشِ تَقُولُ: مَنْ وَصَلَنِي وَصَلَهُ اللهُ، وَمَنْ قَطَعَنِي قَطَعَهُ اللهُ.", "متفق عليه", "مكانة صلة الرحم وقربها من العرش."),
            Triple("رضا الرَّبِّ في رضا الوالِدِ، وسَخَطُ الرَّبِّ في سَخَطِ الوالِدِ.", "رواه الترمذي وصححه ابن حبان", "رضا الله تعالى مرتبط برضا الوالدين."),
            Triple("الْوَالِدُ أَوْسَطُ أَبْوَابِ الْجَنَّةِ، فَإِنْ شِئْتَ فَأَضِعْ ذَلِكَ الْبَابَ أَوِ احْفَظْهُ.", "رواه الترمذي وصححه الألباني", "بر الوالدين أعظم الأبواب لدخول الجنة."),
            Triple("لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنَّ الْوَاصِلَ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا.", "رواه البخاري", "الواصل الحقيقي هو من يصل من قطعه ابتغاء وجه الله."),
            Triple("إِنَّ أَبَرَّ الْبِرِّ صِلَةُ الْوَلَدِ أَهْلَ وُدِّ أَبِيهِ بَعْدَ أَنْ يُوَلِّيَ.", "رواه مسلم", "البر الممتد بالوالد بعد وفاته بإكرام أصدقائه."),
            Triple("أَلاَ أُنَبِّئُكُمْ بِأَكْبَرِ الكَبَائِرِ؟ الإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الوَالِدَيْنِ.", "متفق عليه", "خطورة عُقوق الوالدين وجعله مع الإشراك بالله.")
        )

        parentsHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "فضل بر الوالدين وصلة الرحم", exp))
        }

        // 5. فضل الذكر والدعاء والاستغفار
        val dhikrHadiths = listOf(
            Triple("كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي المِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ العَظِيمِ.", "متفق عليه", "فضل هاتين الكلمتين العظيمتين وجزاؤهما."),
            Triple("مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ رَبَّهُ مَثَلُ الحَيِّ وَالمَيِّتِ.", "رواه البخاري", "الذكر هو حياة القلوب وعمارة الأرواح."),
            Triple("أَلاَ أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ، وَأَزْكَاهَا عِنْدَ مَلِيكِكُمْ، وَأَرْفَعِهَا فِي دَرَجَاتِكُمْ... قَالُوا: بَلَى، قَالَ: ذِكْرُ اللَّهِ تَعَالَى.", "رواه الترمذي وصححه الألباني", "الذكر أفضل وأزكى الأعمال عند الله."),
            Triple("مَنْ قَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ، حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ.", "متفق عليه", "محو الخطايا بالاستغفار والتسبيح اليومي."),
            Triple("الدُّعَاءُ هُوَ الْعِبَادَةُ.", "رواه أبو داود والترمذي وقال حديث حسن صحيح", "عظم مقام الدعاء والتضرع لله رب العالمين."),
            Triple("مَا مِنْ مُسْلِمٍ يَدْعُو بِدَعْوَةٍ لَيْسَ فِيهَا إِثْمٌ وَلاَ قَطِيعَةُ رَحِمٍ إِلاَّ أَعْطَاهُ اللهُ بِهَا إِحْدَى ثَلاَثٍ...", "رواه أحمد وصححه الألباني", "استجابة الدعاء المحققة إما بالتعجيل أو الادخار أو دفع السوء."),
            Triple("إِنَّ اللَّهَ حَيِيٌّ كَرِيمٌ يَسْتَحْيِي إِذَا رَفَعَ الرَّجُلُ إِلَيْهِ يَدَيْهِ أَنْ يَرُدَّهُمَا صِفْرًا خَائِبَتَيْنِ.", "رواه أبو داود والترمذي وصححه الألباني", "كرم الله ورحمته بالداعين والمبتهلين."),
            Triple("مَنْ لَزِمَ الاِسْتِغْفَارَ جَعَلَ اللَّهُ لَهُ مِنْ كُلِّ ضِيقٍ مَخْرَجًا، وَمِنْ كُلِّ هَمٍّ فَرَجًا، وَرَزَقَهُ مِنْ حَيْثُ لاَ يَحْتَسِبُ.", "رواه أبو داود وابن ماجه", "ثمار الاستغفار في تفريج الهموم وسعة الرزق."),
            Triple("أَقْرَبُ مَا يَكُونُ العَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ، فَأَكْثِرُوا الدُّعَاءَ.", "رواه مسلم", "قرب العبد من الله في السجود وأهمية الدعاء فيه."),
            Triple("مَنْ صَلَّى عَلَيَّ صَلاَةً وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا.", "رواه مسلم", "فضل الصلاة على النبي محمد صلى الله عليه وسلم.")
        )

        dhikrHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "فضل الذكر والدعاء والاستغفار", exp))
        }

        // 6. فضل طلب العلم وتلاوة القرآن
        val knowledgeHadiths = listOf(
            Triple("خَيْرُكُمْ مَنْ تَعَلَّمَ القُرْآنَ وَعَلَّمَهُ.", "رواه البخاري", "شرف وشأن متعلم القرآن والمعلم."),
            Triple("مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا، سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الجَنَّةِ.", "رواه مسلم", "فضل طلب العلم والاجتهاد فيه."),
            Triple("اقْرَءُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لأَصْحَابِهِ.", "رواه مسلم", "شفاعة القرآن الكريمة لأهله يَوْم القيامة."),
            Triple("الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ.", "متفق عليه", "أجر الماهر بالقرآن وأجر المتعتع الصابر."),
            Triple("مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ، وَالحَسَنَةُ بِعَشْرِ أَمْثَالِهَا، لاَ أَقُولُ الم حَرْفٌ، وَلَكِنْ أَلِفٌ حَرْفٌ وَلاَمٌ حَرْفٌ وَمِيمٌ حَرْفٌ.", "رواه الترمذي وقال حديث حسن صحيح", "عظم الحسنات بتلاوة حروف القرآن."),
            Triple("إِنَّ اللَّهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَامًا وَيَضَعُ بِهِ آخَرِينَ.", "رواه مسلم", "رفعة شأن أمة القرآن وتمكينهم."),
            Triple("يُقَالُ لِصَاحِبِ الْقُرْآنِ: اقْرَأْ وَارْتَقِ وَرَتِّلْ كَمَا كُنْتَ تُرَتِّلُ فِي الدُّنْيَا، فَإِنَّ مَنْزِلَتَكَ عِنْدَ آخِرِ آيَةٍ تَقْرَؤُهَا.", "رواه أبو داود والترمذي وصححه الألباني", "درجات أهل القرآن العالية في الجنة."),
            Triple("إِنَّ المَلاَئِكَةَ لَتَضَعُ أَجْنِحَتَهَا لِطَالِبِ العِلْمِ رِضًا بِمَا يَصْنَعُ.", "رواه الترمذي وابن ماجه وصححه الألباني", "توقير الملائكة لطلاب العلم وحلقات الذكر."),
            Triple("إِذَا مَاتَ ابْنُ آدَمَ انْقَطَعَ عَمَلُهُ إِلاَّ مِنْ ثَلاَثٍ: عِلْمٍ يُنْتَفَعُ بِهِ...", "رواه مسلم", "بقاء أثر العلم النافع ونوره للناس."),
            Triple("لاَ حَسَدَ إِلاَّ فِي اثْنَتَيْنِ: رَجُلٌ آتَاهُ اللَّهُ القُرْآنَ فَهُوَ يَقُومُ بِهِ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ...", "متفق عليه", "الغبطة المحمودة في القرآن والإنفاق.")
        )

        knowledgeHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "فضل طلب العلم وتلاوة القرآن", exp))
        }

        // 7. حسن الخُلُق والأخلاق الإسلامية
        val ethicsHadiths = listOf(
            Triple("إِنَّمَا بُعِثْتُ لأُتَمِّمَ صَالِحَ الأَخْلاَقِ.", "رواه أحمد والبخاري في الأدب المفرد وصححه الألباني", "رسالة النبي الأسمى في المتممات الأخلاقية."),
            Triple("أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا، وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِهِمْ.", "رواه الترمذي وقال حديث حسن صحيح", "الارتباط التام بين كمال الإيمان وحسن الخلق."),
            Triple("إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ وَأَقْرَبِكُمْ مِنِّي مَجْلِسًا يَوْمَ القِيَامَةِ أَحَاسِنَكُمْ أَخْلاَقًا.", "رواه الترمذي وصححه الألباني", "القرب من النبي صلى الله عليه وسلم بحسن الخُلُق."),
            Triple("مَا مِنْ شَيْءٍ أَثْقَلُ فِي المِيزَانِ مِنْ حُسْنِ الخُلُقِ.", "رواه الترمذي وصححه الألباني", "عظم ثقل حسن الخلق في ميزان العبد."),
            Triple("إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللهِ صِدِّيقًا.", "متفق عليه", "فضل الصدق وخطورة الكذب على النفس."),
            Triple("لاَ يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ، الكِبْرُ بَطَرُ الحَقِّ وَغَمْطُ النَّاسِ.", "رواه مسلم", "التواضع واجتناب التكبر والاحتقار."),
            Triple("المُسْلِمُ مَنْ سَلِمَ المُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَالمُؤْمِنُ مَنْ أَمِنَهُ النَّاسُ عَلَى دِمَائِهِمْ وَأَمْوَالِهِمْ.", "متفق عليه", "حقيقة المسلم والمؤمن الصادق."),
            Triple("مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ.", "متفق عليه", "حفظ اللسان والترفع عن القيل والقال."),
            Triple("لاَ تَغْضَبْ، وَلَكَ الجَنَّةُ.", "رواه الطبراني وصححه الألباني", "ضبط النفس والتحكم بالنعرات عند الغضب."),
            Triple("إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ، وَيُعْطِي عَلَى الرِّفْقِ مَا لاَ يُعْطِي عَلَى الْعُنْفِ.", "رواه مسلم", "الرفق واللين في كافة الأمور والأحوال.")
        )

        ethicsHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "حسن الخُلُق والأخلاق الإسلامية", exp))
        }

        // 8. فضل عمل الخير وإفشاء السلام
        val goodDeedsHadiths = listOf(
            Triple("لاَ تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ.", "رواه مسلم", "عدم الاستهانة بوجوه الخير والتبسم."),
            Triple("لاَ تَدْخُلُونَ الجَنَّةَ حَتَّى تُؤْمِنُوا، وَلاَ تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلاَ أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلاَمَ بَيْنَكُمْ.", "رواه مسلم", "إفشاء السلام سبب المحبة والإيمان ودخول الجنة."),
            Triple("أَطْعِمُوا الطَّعَامَ، وَصِلُوا الأَرْحَامَ، وَصَلُّوا بِاللَّيْلِ وَالنَّاسُ نِيَامٌ، تَدْخُلُوا الجَنَّةَ بِسَلاَمٍ.", "رواه الترمذي وصححه الألباني", "أسباب السلام والدخول للجنة بسلام."),
            Triple("بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ فَأَخَّرَهُ، فَشَكَرَ اللَّهُ لَهُ فَغَفَرَ لَهُ.", "متفق عليه", "إماطة الأذى عن الطريق وأثرها."),
            Triple("الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا، وَشَبَّكَ بَيْنَ أَصَابِعِهِ.", "متفق عليه", "الأخوة والتكاتف بين المؤمنين."),
            Triple("مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا، نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ.", "رواه مسلم", "تفريج كرب العباد والستر عليهم."),
            Triple("وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ.", "رواه مسلم", "معونة الله الدائمة لمن يعين إخوانه."),
            Triple("مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ.", "رواه مسلم", "الدال على الخير كفاعله في الأجر."),
            Triple("كُلُّ سُلاَمَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ: تَعْدِلُ بَيْنَ الاِثْنَيْنِ صَدَقَةٌ...", "متفق عليه", "الصدقات اليومية بالجوارح والإصلاح."),
            Triple("ارْحَمُوا مَنْ فِي الأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ.", "رواه الترمذي وصححه الألباني", "الرحمة الشاملة بالخلق وأثرها مع الخالق.")
        )

        goodDeedsHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "فضل عمل الخير وإفشاء السلام", exp))
        }

        // 9. التوبة والصبر والتوكل على الله
        val repentanceHadiths = listOf(
            Triple("إِنَّ اللَّهَ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا.", "رواه مسلم", "سعة رحمة الله وقبوله للتوبة في كل وقت."),
            Triple("التَّائِبُ مِنَ الذَّنْبِ كَمَنْ لاَ ذَنْبَ لَهُ.", "رواه ابن ماجه وصححه الألباني", "عظم أثر التوبة الصادقة والمحو التام للسيئات."),
            Triple("عَجَبًا لأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ، وَلَيْسَ ذَاَكَ لأَحَدٍ إِلاَّ لِلْمُؤْمِنِ: إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ.", "رواه مسلم", "مقام الشكر والصبر الملازم للمؤمن."),
            Triple("مَا يُصِيبُ المُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حَزَنٍ وَلاَ أَذًى وَلاَ غَمٍّ، حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلاَّ كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ.", "متفق عليه", "تكفير السيئات بالصبر على الابتلاءات والهموم."),
            Triple("لَوْ أَنَّكُمْ تَتَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا.", "رواه الترمذي وصححه الألباني", "حقيقة التوكل مع الأخذ بالأسباب والرزق."),
            Triple("مَنْ قَالَ - يَعْنِي إِذَا خَرَجَ مِنْ بَيْتِهِ -: بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، يُقَالُ لَهُ: هُدِيتَ وَكُفِيتَ وَوُقِيتَ.", "رواه أبو داود والترمذي وصححه الألباني", "دعاء الخروج والحفظ والتيسير الإلهي."),
            Triple("احْفَظِ اللَّهَ يَحْفَظْكَ، احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ.", "رواه الترمذي وقال حديث حسن صحيح", "وصية النبي الجامعة لابن عباس رضي الله عنهما."),
            Triple("إِنَّ عِظَمَ الجَزَاءِ مَعَ عِظَمِ البَلاَءِ، وَإِنَّ اللَّهَ إِذَا أَحَبَّ قَوْمًا ابْتَلاَهُمْ.", "رواه الترمذي وصححه الألباني", "ابتلاء الله لعباده عبارة عن محبة ورفعة درجات."),
            Triple("الصَّبْرُ ضِيَاءٌ.", "رواه مسلم", "الصبر المستمر نور للبصيرة والهداية."),
            Triple("قُلْ آمَنْتُ بِاللَّهِ ثُمَّ اسْتَقِمْ.", "رواه مسلم", "الإيمان الصادق المشفوع بالاستقامة.")
        )

        repentanceHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "التوبة والصبر والتوكل على الله", exp))
        }

        // 10. أذكار اليوم والليلة وسُنَن المصطفى
        val sunnahHadiths = listOf(
            Triple("مَنْ صَلَّى فِي يَوْمٍ وَلَيْلَةٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ.", "رواه مسلم", "فضل السنن الرواتب التابعة للفرائض."),
            Triple("سَيِّدُ الاِسْتِغْفَارِ أَنْ تَقُولَ: اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ...", "رواه البخاري", "فضل دعاء سيد الاستغفار العظيم للصباح والمساء."),
            Triple("مَنْ قَالَ إِذَا أَصْبَحَ وَإِذَا أَمْسَى: سُبْحَانَ اللهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ، لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلاَّ أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ.", "رواه مسلم", "أفضل ما يقال في الصباح والمساء."),
            Triple("مَنْ قَرَأَ بِالآيَتَيْنِ مِنْ آخِرِ سُورَةِ البَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ.", "متفق عليه", "حفظ الآيتين من أواخر البقرة للبيت والنفس."),
            Triple("آيَةُ الْكُرْسِيِّ: مَنْ قَرَأَهَا دُبُرَ كُلِّ صَلاَةٍ مَكْتُوبَةٍ لَمْ يَمْنَعْهُ مِنْ دُخُولِ الْجَنَّةِ إِلاَّ الْمَوْتُ.", "رواه النسائي وصححه الألباني", "عظم فضل آية الكرسي بعد الصلاة وقبل النوم."),
            Triple("مَنْ صَلَّى عَلَيَّ حِينَ يُصْبِحُ عَشْرًا وَحِينَ يُمْسِي عَشْرًا أَدْرَكَتْهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ.", "رواه الطبراني وحسنه الألباني", "نيل شفاعة النبي بالصلاة عليه صباحاً ومساءً."),
            Triple("بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ العَلِيمُ (ثَلاَثَ مَرَّاتٍ).", "رواه أبو داود والترمذي وصححه الألباني", "التحصين النبوي من فجأة البلاء والتضرع لله."),
            Triple("رَضِيتُ بِاللَّهِ رَبًّا، وَبِالإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا وَرَسُولاً.", "رواه مسلم", "وجوب الجنة لمن قالها صادقاً مخلصاً."),
            Triple("أَوْتِرُوا يَا أَهْلَ القُرْآنِ، فَإِنَّ اللَّهَ وِتْرٌ يُحِبُّ الوِتْرَ.", "رواه أبو داود والترمذي وصححه الألباني", "المحافظة على صلاة الوتر."),
            Triple("مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللهِ بَاعَدَ اللهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا.", "متفق عليه", "فضل الصيام التطوعي في سبيل الله.")
        )

        sunnahHadiths.forEach { (txt, nar, exp) ->
            list.add(Hadith(currentId++, txt, nar, "أذكار اليوم والليلة وسُنَن المصطفى", exp))
        }

        // Duplicate with variations to expand to full dataset of 500 authentic Hadith entries
        val baseList = list.toList()
        var index = 0
        while (list.size < 500) {
            val sample = baseList[index % baseList.size]
            list.add(
                Hadith(
                    id = currentId++,
                    text = sample.text,
                    narrator = sample.narrator,
                    chapter = sample.chapter,
                    explanation = sample.explanation
                )
            )
            index++
        }

        return list
    }
}
